import{G as e,W as t,n,rt as r}from"./chunks/framework.OKfwtFe7.js";var i=JSON.parse(`{"title":"反模式导读","description":"","frontmatter":{},"headers":[],"relativePath":"anti-patterns/overview.md","filePath":"anti-patterns/overview.md","lastUpdated":0}`),a={name:`anti-patterns/overview.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="反模式导读" tabindex="-1">反模式导读 <a class="header-anchor" href="#反模式导读" aria-label="Permalink to “反模式导读”">​</a></h1><p>反模式（AntiPattern）是&quot;反复出现、看起来能解决问题、实际让问题变糟&quot;的写法与组织方式。它和模式是同一套词汇的正反两面：模式记的是被验证有效的解法，反模式记的是被验证有害的做法，两者都要求&quot;反复出现&quot;，一次性写歪的代码只能叫 bug。</p><h2 id="三层关系" tabindex="-1">三层关系 <a class="header-anchor" href="#三层关系" aria-label="Permalink to “三层关系”">​</a></h2><p>代码质量问题通常分三层处理，站内对应位置不同：</p><table tabindex="0"><thead><tr><th>层次</th><th>特征</th><th>例子</th><th>处理方式</th></tr></thead><tbody><tr><td>坏味道（Code Smell）</td><td>局部、可机械重构</td><td>过长函数、过大的类、重复代码</td><td>用《重构》[S6] 的手法就地改</td></tr><tr><td>反模式</td><td>结构性、需要先换思路</td><td>神对象、大泥球、金锤子</td><td>先判断形态，再分步迁移</td></tr><tr><td>失败模式</td><td>波及项目与决策</td><td>反复的技术选型摇摆、边写边推翻</td><td>靠流程与评审，不只是代码</td></tr></tbody></table><p>《重构》给第一层，AntiPatterns 那本书 [S7] 给第二、三层，<code>Big Ball of Mud</code> 论文 [S8] 给&quot;系统怎么会烂到这个程度&quot;的完整演化路径。三层的判断标准是作用范围：能靠一次重构收掉的叫坏味道，需要重新划边界与职责的叫反模式。</p><h2 id="本目录四篇-相关篇目" tabindex="-1">本目录四篇 + 相关篇目 <a class="header-anchor" href="#本目录四篇-相关篇目" aria-label="Permalink to “本目录四篇 + 相关篇目”">​</a></h2><ul><li><a href="/hello-design-patterns/anti-patterns/god-object">神对象</a>：一个类握着全局状态，谁改东西都要经过它。</li><li><a href="/hello-design-patterns/anti-patterns/big-ball-of-mud">大泥球</a>：系统没有主线架构，靠修补与补丁维持运转。</li><li><a href="/hello-design-patterns/anti-patterns/golden-hammer">金锤子</a>：手里只有一件工具，所有问题都往它上套。</li><li><a href="/hello-design-patterns/anti-patterns/spaghetti-code">意面代码</a>：控制流靠跳转与共享变量堆出来，改一处崩三处。</li><li><a href="/hello-design-patterns/anti-patterns/anemic-domain-model">贫血模型</a>：对象只有字段与 getter，业务逻辑散在服务里。与<a href="/hello-design-patterns/other/transaction-script">事务脚本</a>对照读。</li></ul><p>这四篇加贫血模型是本次调研补的缺口，差异表见<a href="/hello-design-patterns/research/coverage">覆盖核对</a>。</p><h2 id="反模式的三段写法" tabindex="-1">反模式的三段写法 <a class="header-anchor" href="#反模式的三段写法" aria-label="Permalink to “反模式的三段写法”">​</a></h2><p>站内每篇反模式按同一个顺序写，方便横向比较：</p><ol><li><strong>形态</strong>：看到什么就该起疑，给可数的特征（几个字段、几条 import、多大扇出）。</li><li><strong>代价</strong>：它具体伤到什么，写成可验证的描述（改一个字段要跟着改 7 个类、单测要 mock 掉半个系统）。</li><li><strong>成因</strong>：系统怎么一步步滑进去，避免只在结果上贴标签。</li><li><strong>走出来</strong>：能一步到位的给手法，只能分步的给迁移顺序，标明哪一步之后可以停。</li></ol><h2 id="与模式的关系" tabindex="-1">与模式的关系 <a class="header-anchor" href="#与模式的关系" aria-label="Permalink to “与模式的关系”">​</a></h2><p>反模式不是模式的反义词，两者经常是同一件事的两面：</p><ul><li>单例用在&quot;确实全局唯一&quot;的资源上是<a href="/hello-design-patterns/creational/singleton">单例模式</a>，用它来省掉依赖传递就滑向<a href="/hello-design-patterns/anti-patterns/god-object">神对象</a>；</li><li><a href="/hello-design-patterns/creational/service-locator">服务定位器</a> 与<a href="/hello-design-patterns/structural/dependency-injection">依赖注入</a>解决同一个查找问题，前者被 Fowler 列为服务定位器反模式 [S26]，理由是它把依赖藏进实现里，单测时看不出来；</li><li><a href="/hello-design-patterns/behavioral/strategy">策略</a>、<a href="/hello-design-patterns/behavioral/state">状态</a> 这类&quot;把分支抽出去&quot;的模式，正是意面代码走出来的第一步。</li></ul><p>判断线在于有没有把&quot;谁依赖谁&quot;写清楚：能被类型系统或构造函数看出来的依赖是模式，只能靠读全局变量猜的依赖是反模式。</p><h2 id="怎么用这个目录" tabindex="-1">怎么用这个目录 <a class="header-anchor" href="#怎么用这个目录" aria-label="Permalink to “怎么用这个目录”">​</a></h2><ol><li>先对照形态一节确认是不是真的中了，别把&quot;类有点大&quot;直接判成神对象。</li><li>看代价一节，判断现在疼不疼。不疼的反模式可以先记着，不必立刻动。</li><li>走出来一节给的是迁移顺序，不是重写方案；每篇都标了可以停在哪一步。</li><li>想知道这些反模式是怎么被系统化记录的，见<a href="/hello-design-patterns/research/books">权威书籍与标准目录</a>的 AntiPatterns 一节 [S7]。</li></ol><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to “来源”">​</a></h2><ul><li>[S6] Martin Fowler 等，《Refactoring》第 2 版，2018。坏味道目录。</li><li>[S7] Brown 等，《AntiPatterns》，Wiley，1998。反模式目录。</li><li>[S8] Foote、Yoder，《Big Ball of Mud》，PLoP 1997。</li><li>[S25] Wikipedia 的 Software antipattern、God object 词条，用于核对别名。</li><li>[S26] martinfowler.com 的 bliki 与企业应用模式目录。</li></ul>`,20)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};